attempts.query:
PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (SUM(?sr) AS ?total) WHERE {
  {
    SELECT DISTINCT ?d WHERE {
      ?l rdfs:label "Lung Neoplasms"@en .
      ?c oncologia:within ?l .
      ?t a oncologia:Trial ; oncologia:condition ?c ; oncologia:status ?st ; oncologia:testsDrug ?d .
      FILTER(?st IN ("RECRUITING", "ACTIVE_NOT_RECRUITING", "NOT_YET_RECRUITING", "ENROLLING_BY_INVITATION"))
      ?d oncologia:hasTarget ?tg . ?tg oncologia:gene "EGFR" .
    }
  }
  ?y a oncologia:YearlyReports ; oncologia:drug ?d ; oncologia:seriousReports ?sr .
}
